def proverb(*items, qualifier=None):
    if not items:
        return []

    lines = [
        f"For want of a {current} the {next_item} was lost."
        for current, next_item in zip(items, items[1:])
    ]

    subject = items[0] if not qualifier else f"{qualifier} {items[0]}"
    lines.append(f"And all for the want of a {subject}.")
    return lines

